-- Skirmish engine: units, buildings and research for the Human Alliance, the Orcish Horde and the Undead Scourge and the Night Elf Sentinels.
-- GENERATED from Warcraft III's own unit tables (UnitBalance, UnitWeapons, UnitData, UpgradeData
-- and the Human/Orc tech-tree files) by gen.py; costs, hit points, armour, damage, cooldowns, ranges
-- and speeds are the real numbers. WC3 distances are converted at 128 game units to a map tile.
-- Models are WoW's: creature display IDs of matching classic NPCs, and world doodads for buildings.

local _, ns = ...
ns.Engine = ns.Engine or {}
local E = ns.Engine
local D = {}
E.Data = D

D.MAP_W, D.MAP_H = 64, 64
D.TICK = 0.1
D.MAX_SUPPLY = 100                 -- Warcraft III's food cap
D.UPKEEP = { { 50, 1.0 }, { 80, 0.7 }, { 100, 0.4 } }   -- food used -> share of mined gold you keep
D.START_GOLD, D.START_LUMBER = 500, 150
D.MINE_GOLD = 12500
D.TREE_LUMBER = 50
D.GOLD_TRIP, D.LUMBER_TRIP = 10, 10
D.MINE_TIME = 1.0                  -- one worker inside a mine at a time
D.CHOP_TIME = 1.1                  -- per point of lumber (a peasant's swing at a tree)
D.HERO_XP = { 0, 200, 500, 900, 1400, 2000, 2700, 3500, 4400, 5400 }
D.HERO_MAX_LEVEL = 10
D.REGEN = 0.25                     -- hit points per second for living units, as in WC3

D.Factions = {
    alliance = { name = "Human Alliance", short = "Humans", hall = "townHall", halls = { "townHall", "keep", "castle" },
                 worker = "peasant", farm = "farm", barracks = "barracks", altar = "altarKings", tower = "scoutTower",
                 lumberMill = "lumberMill", smith = "blacksmith", color = { 0.25, 0.55, 1.0 } },
    orcs     = { name = "Orcish Horde", short = "Orcs", hall = "greatHall", halls = { "greatHall", "stronghold", "fortress" },
                 worker = "peon", farm = "burrow", barracks = "orcBarracks", altar = "altarStorms", tower = "watchTower",
                 lumberMill = "warMill", smith = "warMill", color = { 1.0, 0.25, 0.2 } },
    undead   = { name = "Undead Scourge", short = "Undead", hall = "necropolis", halls = { "necropolis", "hallsOfTheDead", "blackCitadel" },
                 worker = "acolyte", farm = "ziggurat", barracks = "crypt", altar = "altarDarkness", tower = "ziggurat",
                 lumberMill = "graveyard", smith = "graveyard", gatherer = "ghoul", mineBuilding = "hauntedMine", startWorkers = 3, color = { 0.55, 0.3, 0.85 } },
    nightelf = { name = "Night Elf Sentinels", short = "Night Elves", hall = "treeOfLife", halls = { "treeOfLife", "treeOfAges", "treeOfEternity" },
                 worker = "wisp", farm = "moonWell", barracks = "ancientWar", altar = "altarElders", tower = "ancientProtector",
                 lumberMill = "huntersHall", smith = "huntersHall", mineBuilding = "entangledMine", entangleMine = true, color = { 0.3, 0.85, 0.55 } },
}
D.FactionOrder = { "alliance", "orcs", "undead", "nightelf" }

-- A hall counts as every tier below it (a Castle is also a Keep and a Town Hall).
D.Counts = {
    keep = { "castle" }, townHall = { "keep", "castle" },
    stronghold = { "fortress" }, greatHall = { "stronghold", "fortress" },
    hallsOfTheDead = { "blackCitadel" }, necropolis = { "hallsOfTheDead", "blackCitadel" },
    ziggurat = { "spiritTower", "nerubianTower" },
    treeOfAges = { "treeOfEternity" }, treeOfLife = { "treeOfAges", "treeOfEternity" },
}

-- Warcraft III's damage table: attack type -> armour type -> multiplier.
-- Armour reduces damage by 0.06a / (1 + 0.06a).
D.ATTACK_VS = {
    normal = { light = 1.0, medium = 1.5, heavy = 1.0, fortified = 0.7, hero = 1.0, unarmored = 1.0 },
    pierce = { light = 2.0, medium = 0.75, heavy = 1.0, fortified = 0.35, hero = 0.5, unarmored = 1.5 },
    siege  = { light = 1.0, medium = 0.5, heavy = 1.0, fortified = 1.5, hero = 0.5, unarmored = 1.5 },
    magic  = { light = 1.25, medium = 0.75, heavy = 2.0, fortified = 0.35, hero = 0.5, unarmored = 1.0 },
    chaos  = { light = 1.0, medium = 1.0, heavy = 1.0, fortified = 1.0, hero = 1.0, unarmored = 1.0 },
    hero   = { light = 1.0, medium = 1.0, heavy = 1.0, fortified = 0.5, hero = 1.0, unarmored = 1.0 },
}
D.ARMOR_NAMES = { light = "Light", medium = "Medium", heavy = "Heavy", fortified = "Fortified", hero = "Hero", unarmored = "Unarmoured" }
D.ATTACK_NAMES = { normal = "Normal", pierce = "Piercing", siege = "Siege", magic = "Magic", chaos = "Chaos", hero = "Hero" }

D.Units, D.Buildings, D.Research = {}, {}, {}
local function U(t)
    t.kind = "unit"
    t.supply = t.supply or 1
    t.armor = t.armor or 0
    t.lumber = t.lumber or 0
    t.sight = t.sight or 8
    if t.hitsGround == nil and t.hitsAir == nil then t.hitsGround = true end
    D.Units[t.id] = t
end
local function B(t)
    t.kind = "building"
    t.lumber = t.lumber or 0
    t.supplyGiven = t.supplyGiven or 0
    t.armor = t.armor or 5
    t.dtype = t.dtype or "fortified"
    t.sight = t.sight or 8
    if t.attack and t.attack.hitsGround == nil then t.attack.hitsGround = true end
    D.Buildings[t.id] = t
end
local function R(t)
    t.kind = "research"
    D.Research[t.id] = t
end


