D.BuildMenu = {
    alliance = { "townHall", "farm", "barracks", "lumberMill", "blacksmith", "altarKings", "scoutTower", "workshop", "arcaneSanctum", "gryphonAviary", "arcaneVault" },
    orcs = { "greatHall", "burrow", "orcBarracks", "warMill", "altarStorms", "watchTower", "beastiary", "spiritLodge", "taurenTotem", "voodooLounge" },
    nightelf = { "treeOfLife", "moonWell", "ancientWar", "huntersHall", "altarElders", "ancientProtector", "ancientLore", "ancientWind", "ancientWonders", "chimaeraRoost" },
    undead = { "necropolis", "ziggurat", "crypt", "graveyard", "altarDarkness", "hauntedMine", "temple", "slaughterhouse", "tombRelics", "sacrificialPit", "boneyard" },
}
-- buildings with no requirement listed in WC3 still need a hall to exist
for _, list in pairs(D.BuildMenu) do
    for _, id in ipairs(list) do
        local b = D.Buildings[id]
        if not b.requires and not b.hall then b.requires = { D.Factions[b.faction].hall } end
    end
end
-- what each building can research
for _, r in pairs(D.Research) do
    local b = D.Buildings[r.at]
    b.researches = b.researches or {}
    table.insert(b.researches, r.id)
end
for _, b in pairs(D.Buildings) do
    if b.researches then table.sort(b.researches, function(x, y) return D.Research[x].wc3 < D.Research[y].wc3 end) end
end
-- a hall's research list carries over to the tiers above it
D.Buildings.keep.researches, D.Buildings.castle.researches = D.Buildings.townHall.researches, D.Buildings.townHall.researches
D.Buildings.stronghold.researches, D.Buildings.fortress.researches = D.Buildings.greatHall.researches, D.Buildings.greatHall.researches
D.Buildings.hallsOfTheDead.researches, D.Buildings.blackCitadel.researches = D.Buildings.necropolis.researches, D.Buildings.necropolis.researches
D.Buildings.treeOfAges.researches, D.Buildings.treeOfEternity.researches = D.Buildings.treeOfLife.researches, D.Buildings.treeOfLife.researches

