function D.xpFor(def, level)
    if def.hero then return 100 + 100 * (level or 1) end
    if def.kind == "building" then return 0 end
    return 25 + 15 * (def.supply or 1)
end

function D.def(id) return D.Units[id] or D.Buildings[id] or D.Research[id] end

-- neutral creeps get their size, pace and weapons here (they're defined with the simulation)
D.FEEL = {
    ogre = { r = 0.45, s = 2.0, range = 0.5 }, ogreMauler = { r = 0.5, s = 2.0, range = 0.55 },
}
D.GEAR = { ogre = { main = 2809 }, ogreMauler = { main = 5289 } }
function D.applyFeel()
    for id, f in pairs(D.FEEL) do
        local u = D.Units[id]
        if u and not u.vis then
            u.vis = u.radius
            u.radius = f.r
            u.speed = f.s
            if f.range then u.range = f.range end
            u.gear = D.GEAR[id]
            u.hitsGround, u.hitsBuildings = true, true
        end
    end
end

